"""Paper figures (PDF + PNG at 300 dpi + the CSV of plotted values). Regenerated by run_all.py."""
from __future__ import annotations

from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
from matplotlib.patches import FancyBboxPatch  # noqa: E402

from . import config as C  # noqa: E402

plt.rcParams.update({"font.size": 9, "axes.titlesize": 9.5, "axes.labelsize": 9, "legend.fontsize": 8,
                     "figure.dpi": 100, "savefig.bbox": "tight", "axes.spines.top": False, "axes.spines.right": False})
COLORS = {"LightGBM": "#0072B2", "CatBoost": "#E69F00", "FT-Transformer": "#009E73", "NGBoost": "#CC79A7",
          "LightGBM-L1": "#D55E00", "NGBoost P(Y<60)": "#7F3C8D"}
LABELS = [C.MODELS[k]["label"] for k in C.MODEL_ORDER]


def _save(fig, data: pd.DataFrame, out: Path, stem: str):
    out.mkdir(parents=True, exist_ok=True)
    fig.savefig(out / f"{stem}.pdf")
    fig.savefig(out / f"{stem}.png", dpi=300)
    plt.close(fig)
    data.to_csv(out / f"{stem}.csv", index=False, encoding="utf-8-sig")


def fig1_flow(counts: dict, out: Path):
    fig, ax = plt.subplots(figsize=(7.2, 5.0))
    ax.set_xlim(0, 100)
    ax.set_ylim(0, 100)
    ax.axis("off")

    def box(x, y, w, h, text, fc="#F2F2F2", ec="#555555", bold=False, fs=6.9):
        ax.add_patch(FancyBboxPatch((x, y), w, h, boxstyle="round,pad=0.4,rounding_size=1.5", fc=fc, ec=ec, lw=0.8))
        ax.text(x + w / 2, y + h / 2, text, ha="center", va="center", fontsize=fs, weight="bold" if bold else "normal")

    def arrow(x0, y0, x1, y1):
        ax.annotate("", xy=(x1, y1), xytext=(x0, y0), arrowprops=dict(arrowstyle="-|>", lw=0.8, color="#444444"))

    steps = [f"Registrar export\n{counts['raw_rows']:,d} enrolments",
             f"Study term 113-2\n{counts['term_rows']:,d} enrolments",
             f"Exclude unexplained\nzero grades\n(n = {counts['zero_rows']:,d})",
             f"Analysis set\n{counts['analysis_rows']:,d} enrolments\n{counts['students']:,d} students"]
    xs = [1, 26, 51, 76]
    for i, (x, s) in enumerate(zip(xs, steps)):
        box(x, 84, 21.5, 12, s, fc="#DCEAF7" if i == 3 else "#F2F2F2", bold=i == 3)
        if i:
            arrow(xs[i - 1] + 22.3, 90, x - 0.8, 90)
    box(1, 59, 52, 14, "Existing out-of-fold predictions of the IR study\n5-fold student-grouped CV, seed 42 (unseen students)\n"
        "registration-time features only\nLightGBM | CatBoost | FT-Transformer | NGBoost | LightGBM-L1", fc="#FFF4D6", fs=6.4)
    box(57, 59, 42, 14, "Pre-specified follow-ups (refitted models)\nsame folds; training folds split by student\n"
        "into 80% fit / 20% calibration\nLightGBM L2, L1, classifier, quantile, weighted;\n"
        f"NGBoost; also with zeros (n = {counts['term_rows']:,d})", fc="#FCE9D9", fs=6.2)
    arrow(86.5, 83.2, 27, 73.8)
    arrow(86.5, 83.2, 78, 73.8)
    box(1, 44, 52, 8, "Alignment audit: data SHA-256, row order, fold partition,\ntargets, registered MAE / RMSE",
        fc="#EAF5EA", fs=6.4)
    box(57, 44, 42, 8, "Checks: student-disjoint fit / calibration / test;\nreproduction of saved predictions", fc="#EAF5EA", fs=6.4)
    arrow(27, 58.2, 27, 52.8)
    arrow(78, 58.2, 78, 52.8)
    labels = ["RQ1 Overall error\nMAE, RMSE", "RQ1 Risk identification\nP, R, F1, PR-AUC, ROC-AUC\n+ tuned thresholds,\n"
              "objectives, zero grades", "RQ2 Grade-range bias\nsigned error by\nactual grade range",
              "RQ3 Uncertainty\nNLL, coverage, width\n+ conformal, CQR,\nrecalibration"]
    for i, t in enumerate(labels):
        x = 1 + i * 25
        box(x, 17, 22, 18, t, fc="#F7E1EA" if i == 3 else "#EEEEEE", fs=6.4)
        arrow(27, 43.2, x + 11, 35.8)
    for i in (1, 3):
        arrow(78, 43.2, 1 + i * 25 + 13, 35.8)
    box(6, 1, 88, 8.5, "Paired student-cluster bootstrap (5,000 replicates, seed 42); Holm / Bonferroni control; "
        "exploratory, single semester", fc="#DCEAF7", fs=6.4)
    for i in range(4):
        arrow(12 + i * 25, 16.2, 50, 10.3)
    data = pd.DataFrame({"step": ["raw", "term", "zeros_excluded", "analysis", "students"],
                         "n": [counts["raw_rows"], counts["term_rows"], counts["zero_rows"], counts["analysis_rows"], counts["students"]]})
    _save(fig, data, out, "figure1_workflow")


def fig2_error(per_model: pd.DataFrame, out: Path):
    fig, axes = plt.subplots(1, 2, figsize=(7.2, 2.8))
    rows = []
    for ax, m in zip(axes, ["MAE", "RMSE"]):
        d = per_model[per_model.metric == m].set_index("model").loc[C.MODEL_ORDER]
        x = np.arange(len(d))
        err = np.vstack([d["estimate"] - d["ci_low"], d["ci_high"] - d["estimate"]])
        ax.bar(x, d["estimate"], color=[COLORS[l] for l in LABELS], yerr=err, capsize=3, width=0.65)
        for xi, v in zip(x, d["estimate"]):
            ax.text(xi, v + err[1].max() + 0.04, f"{v:.3f}", ha="center", fontsize=7)
        lo = d["ci_low"].min()
        ax.set_ylim(lo - (0.8 if m == "MAE" else 1.0), d["ci_high"].max() + 0.35)
        ax.set_xticks(x, LABELS, rotation=25, ha="right")
        ax.set_ylabel(f"{m} (grade points)")
        ax.set_title(f"({'a' if m == 'MAE' else 'b'}) {m}, lower is better")
        rows += [{"model": l, "metric": m, "estimate": e, "ci_low": a, "ci_high": b}
                 for l, e, a, b in zip(LABELS, d["estimate"], d["ci_low"], d["ci_high"])]
    fig.text(0.5, -0.2, "Bars: point estimates; whiskers: 95% student-cluster bootstrap CI. y-axes truncated.", ha="center", fontsize=7.5)
    _save(fig, pd.DataFrame(rows), out, "figure2_mae_rmse")


def fig3_risk(per_model: pd.DataFrame, pr: pd.DataFrame, prevalence: float, out: Path):
    fig, axes = plt.subplots(1, 2, figsize=(7.4, 3.0), gridspec_kw={"width_ratios": [1.35, 1]})
    ax = axes[0]
    mets = [("precision", "Precision"), ("recall", "Recall"), ("f1", "F1")]
    w = 0.16
    rows = []
    for i, k in enumerate(C.MODEL_ORDER):
        d = per_model[per_model.model == k].set_index("metric")
        est = [d.loc[m, "estimate"] for m, _ in mets]
        err = np.array([[d.loc[m, "estimate"] - d.loc[m, "ci_low"], d.loc[m, "ci_high"] - d.loc[m, "estimate"]] for m, _ in mets]).T
        ax.bar(np.arange(3) + (i - 2) * w, est, w, yerr=err, capsize=2, color=COLORS[LABELS[i]], label=LABELS[i])
        rows += [{"model": LABELS[i], "metric": m, "estimate": d.loc[m, "estimate"], "ci_low": d.loc[m, "ci_low"],
                  "ci_high": d.loc[m, "ci_high"]} for m, _ in mets]
    ax.set_xticks(np.arange(3), [n for _, n in mets])
    ax.set_ylim(0, 0.52)
    ax.set_ylabel("Value")
    ax.set_title("(a) Fixed rule: predicted grade < 60")
    ax.legend(ncol=2, frameon=False, loc="upper left", fontsize=7)
    ax = axes[1]
    for name, g in pr.groupby("model", sort=False):
        ls = "--" if "P(Y<60)" in name else "-"
        ax.plot(g["recall"], g["precision"], ls, lw=1.1, color=COLORS.get(name, "#333333"), label=name)
    ax.axhline(prevalence, color="#999999", lw=0.8, ls=":", label=f"Prevalence ({prevalence:.3f})")
    ax.set_xlim(0, 1)
    ax.set_ylim(0, 1)
    ax.set_xlabel("Recall")
    ax.set_ylabel("Precision")
    ax.set_title("(b) Precision-recall curves (ranking)")
    ax.legend(frameon=False, fontsize=6.3, loc="upper right")
    fig.text(0.5, -0.06, "Positive class: actual grade < 60. Ranking score = −predicted grade (not a probability); "
             "dashed: NGBoost P(Y<60). Whiskers: 95% bootstrap CI.", ha="center", fontsize=7.2)
    _save(fig, pd.concat([pd.DataFrame(rows), pr.assign(metric="pr_curve")], ignore_index=True), out, "figure3_risk_identification")


def fig4_bias(bias: pd.DataFrame, out: Path):
    fig, axes = plt.subplots(1, 2, figsize=(7.4, 2.9))
    ranges = [b for b, _, _ in C.GRADE_BANDS]
    w = 0.16
    ax = axes[0]
    for i, l in enumerate(LABELS):
        d = bias[bias.model == l].set_index("grade_range").loc[ranges]
        ax.bar(np.arange(5) + (i - 2) * w, d["mean_signed_error"], w, color=COLORS[l], label=l)
    ax.axhline(0, color="black", lw=0.6)
    ax.set_xticks(np.arange(5), ranges)
    ax.set_xlabel("Actual grade range")
    ax.set_ylabel("Mean signed error (pred − actual)")
    ax.set_title("(a) Over- and under-estimation")
    ax.legend(frameon=False, fontsize=6.8)
    ax = axes[1]
    for l in LABELS:
        d = bias[bias.model == l].set_index("grade_range").loc[ranges]
        ax.plot(d["mean_actual"], d["mean_predicted"], "o-", ms=3.5, lw=1.1, color=COLORS[l], label=l)
    lim = (25, 100)
    ax.plot(lim, lim, color="#999999", lw=0.8, ls=":", label="Identity")
    ax.axhline(60, color="#BBBBBB", lw=0.6, ls="--")
    ax.set_xlim(*lim)
    ax.set_ylim(*lim)
    ax.set_xlabel("Mean actual grade in range")
    ax.set_ylabel("Mean predicted grade")
    ax.set_title("(b) Compression toward the centre")
    fig.text(0.5, -0.06, "Ranges are defined by the actual grade (post-hoc strata, not model inputs); dashed line at 60.",
             ha="center", fontsize=7.2)
    _save(fig, bias.drop(columns=["key"]), out, "figure4_grade_range_bias")


def fig5_calibration(iv: pd.DataFrame, rel: pd.DataFrame, out: Path):
    names = {"normal_raw": "Normal (raw)", "normal_rescaled": "Normal (in-fold rescaled)",
             "cf_absolute": "CF conformal, absolute", "cf_normalised": "CF conformal, normalised",
             "cf_mondrian": "CF Mondrian (category)"}
    sty = {"normal_raw": ("#CC79A7", "o-"), "normal_rescaled": ("#882255", "s--"), "cf_absolute": ("#0072B2", "^-"),
           "cf_normalised": ("#009E73", "D-"), "cf_mondrian": ("#E69F00", "v:")}
    fig, axes = plt.subplots(2, 2, figsize=(7.2, 5.6))
    a = iv[iv.group_by == "all"]
    for m, n in names.items():
        d = a[a.method == m].sort_values("nominal")
        c, s = sty[m]
        axes[0, 0].plot(d["nominal"], d["coverage"] - d["nominal"], s, color=c, ms=3.5, lw=1.1, label=n)
        axes[0, 1].plot(d["nominal"], d["mean_width"], s, color=c, ms=3.5, lw=1.1, label=n)
    axes[0, 0].axhline(0, color="black", lw=0.6)
    axes[0, 0].set_xlabel("Nominal coverage")
    axes[0, 0].set_ylabel("Empirical − nominal coverage")
    axes[0, 0].set_title("(a) Coverage error")
    axes[0, 0].legend(frameon=False, fontsize=6.5)
    axes[0, 1].set_xlabel("Nominal coverage")
    axes[0, 1].set_ylabel("Mean interval width (grade points)")
    axes[0, 1].set_title("(b) Interval width")
    ax = axes[1, 0]
    ranges = [b for b, _, _ in C.GRADE_BANDS]
    w = 0.16
    for i, m in enumerate(names):
        d = iv[(iv.method == m) & (iv.nominal == 0.9) & (iv.group_by == "grade_range")].set_index("group").loc[ranges]
        ax.bar(np.arange(5) + (i - 2) * w, d["coverage"], w, color=sty[m][0], label=names[m])
    ax.axhline(0.9, color="black", lw=0.7, ls="--")
    ax.set_xticks(np.arange(5), ranges)
    ax.set_ylim(0, 1.05)
    ax.set_xlabel("Actual grade range")
    ax.set_ylabel("Empirical coverage")
    ax.set_title("(c) 90% intervals by actual grade range")
    ax = axes[1, 1]
    r = rel[(rel.threshold == "60") & (rel.version == "normal_raw") & (rel.n > 0)]
    ax.plot([0, 1], [0, 1], color="#999999", lw=0.8, ls=":")
    ax.plot(r["mean_predicted"], r["observed_rate"], "o-", color="#CC79A7", ms=3.5, lw=1.1)
    for _, q in r.iterrows():
        ax.annotate(f"{int(q['n']):,d}", (q["mean_predicted"], q["observed_rate"]), fontsize=5.5, xytext=(3, -7),
                    textcoords="offset points")
    ax.set_xlim(0, 1)
    ax.set_ylim(0, 1)
    ax.set_xlabel("Predicted P(Y < 60)")
    ax.set_ylabel("Observed share with grade < 60")
    ax.set_title("(d) Reliability of NGBoost P(Y<60)")
    fig.tight_layout()
    fig.text(0.5, -0.02, "CF = cross-fold conformal (post-hoc; quantiles from the other four folds; no separate calibration set). "
             "Labels in (d): records per bin.", ha="center", fontsize=7)
    _save(fig, pd.concat([iv.assign(panel="a-c"), rel.assign(panel="d")], ignore_index=True), out, "figure5_ngboost_calibration")


def figS1_pit(pit: pd.DataFrame, out: Path):
    fig, ax = plt.subplots(figsize=(3.6, 2.6))
    ax.bar(pit["bin_lower"] + 0.025, pit["count"], width=0.048, color="#CC79A7")
    ax.axhline(pit["expected_uniform"].iat[0], color="black", lw=0.7, ls="--")
    ax.set_xlabel("PIT value Φ((y − μ)/σ)")
    ax.set_ylabel("Records")
    ax.set_title("NGBoost probability integral transform")
    _save(fig, pit, out, "figureS1_ngboost_pit")


def figS2_category(iv: pd.DataFrame, out: Path):
    d = iv[(iv.nominal == 0.9) & (iv.group_by == "course_category")]
    piv = d.pivot_table(index="group_en", columns="method", values="coverage")
    fig, ax = plt.subplots(figsize=(5.8, 2.8))
    cols = ["normal_raw", "normal_rescaled", "cf_absolute", "cf_normalised", "cf_mondrian"]
    w = 0.16
    for i, m in enumerate(cols):
        ax.bar(np.arange(len(piv)) + (i - 2) * w, piv[m], w, label=m)
    ax.axhline(0.9, color="black", lw=0.7, ls="--")
    ax.set_xticks(np.arange(len(piv)), piv.index, rotation=15, ha="right")
    ax.set_ylim(0.7, 1.0)
    ax.set_ylabel("Empirical coverage")
    ax.set_title("90% intervals by course category")
    ax.legend(frameon=False, fontsize=6.5, ncol=3)
    _save(fig, d, out, "figureS2_coverage_by_course_category")
